buildSystemPrompt(capabilities: Capability[], taskDescription?: string): string {
  const availableCapabilities = capabilities.filter((c) => c.status === 'available');

  if (availableCapabilities.length === 0) {
    return DEFAULT_SYSTEM_PROMPT;
  }

  // Select relevant capabilities to reduce prompt size
  const relevantCapabilities = taskDescription
    ? this.selectRelevantCapabilities(availableCapabilities as CapabilityForPrompt[], taskDescription)
    : availableCapabilities;

  const capabilitiesSection = this.formatCapabilities(relevantCapabilities as Capability[]);
  return buildSystemPromptTemplate(capabilitiesSection);
}

